import sys

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        N = int(input[ptr])
        ptr += 1
        B = list(map(int, input[ptr:ptr+N]))
        ptr += N

        A = []
        current_mex = 0
        used = set()
        valid = True
        for i in range(N):
            if B[i] != -1:
                if B[i] < current_mex:
                    valid = False
                    break
                if B[i] in used:
                    valid = False
                    break
                if B[i] != current_mex:
                    A.append(B[i])
                    used.add(B[i])
                    current_mex = B[i] + 1
                else:
                    A.append(B[i] + 1)
                    used.add(B[i] + 1)
                    current_mex = B[i] + 1
            else:
                if current_mex in used:
                    A.append(current_mex + 1)
                    used.add(current_mex + 1)
                else:
                    A.append(current_mex)
                    used.add(current_mex)
        if valid:
            print(' '.join(map(str, A)))
        else:
            print(-1)

solve()
